/**
 * The map: tiles, wires, panning and zooming.
 *
 * The drawing library owns four things and no more — panning, zooming, working
 * out what is under the pointer, and the sockets on the sides of a tile.
 * Everything you can see is ours. That is why only the library's bare
 * stylesheet is imported below and never its full one: the full one carries the
 * library's own look, and a tool that looks like the library it was built with
 * looks like a demo. A check in `npm run lint` fails the build if the full one
 * ever appears in this tree.
 *
 * Three things this file works out that no single wire could work out for
 * itself, because a wire cannot see where the other tiles are:
 *
 *   1. **How each wire is routed.** Most arrows join neighbouring columns and
 *      take the ordinary route. An arrow that skips a column would run straight
 *      through the tile in between and disappear behind it, so it is given a
 *      clear corridor to travel along instead; and the one arrow that runs
 *      backwards is sent over the top of the map, where there is nothing to
 *      cross.
 *   2. **The hover lens.** Point at a claim and everything not on its path —
 *      neither one of its causes nor one of the things it causes — drops to
 *      fifteen per cent.
 *   3. **Whether a wire's plate has room for its words.** Below the same zoom at
 *      which a tile switches to its summary, a plate's words would land under
 *      eleven pixels on the glass, so the plates go. Nothing is scaled down to
 *      dodge the rule.
 */

import {
  Background,
  BackgroundVariant,
  Controls,
  ReactFlow,
  ReactFlowProvider,
  useNodesInitialized,
  useReactFlow,
  useStore,
  useUpdateNodeInternals,
} from "@xyflow/react";
import { type ReactNode, useCallback, useEffect, useMemo, useRef, useState } from "react";
import "@xyflow/react/dist/base.css";
import { SkeletonTile } from "../components/SkeletonTile";
import { Tile } from "../components/Tile";
import { TileOverflow } from "../components/TileOverflow";
import type { Edges } from "../components/useTheEdges";
import { edgeMarks, NOTHING_BEYOND } from "../components/useTheEdges";
import type { MapKeys } from "../keyboard/useMapKeys";
import { useMapKeys } from "../keyboard/useMapKeys";
import type { Selection, WorldView } from "../world";
import { NOT_ON_THIS_MAP } from "../world/naming";
import {
  firstFrame,
  LARGEST_ZOOM,
  SMALLEST_ZOOM,
  SUMMARY_BELOW_ZOOM,
  TILE_WIDTH,
} from "./geometry";
import { assignLayers } from "./layers";
import { useLayout } from "./layoutRunner";
import { mayLandAgain } from "./theKeyboard";
import {
  type ClaimNode,
  type MapEdge,
  type MapNode,
  OVERFLOW_PREFIX,
  type OverflowNode,
  RESERVED_PREFIX,
  type ReservedBox,
  type SkeletonNode,
  toFlow,
} from "./toFlow";
import { CausalWire } from "./wires/CausalWire";
import { onThePathFrom } from "./wires/lens";
import { planPlates } from "./wires/plates";
import { type Box, planRoutes, SKY_GAP, tailOffsets } from "./wires/route";
import { ARROWHEAD, WireMarks } from "./wires/WireMarks";
import "./canvas.css";

/** The two kinds of box the map draws. Defined once, outside render, so the
 * drawing library never has to rebuild its tiles because the object changed. */
const TILE_TYPES = {
  claim: ({ data }: { data: ClaimNode["data"] }) => (
    <Tile
      claim={data.claim}
      isHypothesis={data.isHypothesis}
      versions={data.versions}
      height={data.height}
    />
  ),
  overflow: ({ data }: { data: OverflowNode["data"] }) => <TileOverflow count={data.count} />,
  skeleton: ({ data }: { data: SkeletonNode["data"] }) => <SkeletonTile words={data.words} />,
};

/** One kind of wire, ours, saying five things at once. */
const WIRE_TYPES = { causal: CausalWire };

/** What the map needs beyond the world it draws. */
interface SurfaceProps {
  /** The world to draw. */
  readonly world: WorldView;
  /** What the panel beside the map is open on. */
  readonly selection: Selection;
  /** Called when the reader selects a claim or an arrow, by pointer or by keyboard. */
  readonly onSelect: (selection: Selection) => void;
  /** Which claim the keyboard is on. Held outside the map, because the keys are. */
  readonly focused: string | null;
  /** Put the keyboard on a claim. */
  readonly onFocused: (id: string | null) => void;
  /**
   * How tall to draw each tile, when a diff needs one box to hold two paintings.
   * Left out, each tile is as tall as its own content.
   */
  readonly heights?: ReadonlyMap<string, number>;
  /**
   * Which map this is: the base map, or the base map with one branch folded on.
   *
   * Both paintings of one diff share it, so flipping between them moves nothing.
   * Opening a different branch changes it, and the union of the two worlds is
   * then laid out again from scratch — one layout, two paintings.
   */
  readonly mapKey: string;
  /** Everything the keys that are not about moving are wired to. */
  readonly keys: MapKeys;
  /** Say what the last keystroke did, under the map. */
  readonly onStatus: (line: string) => void;
  /**
   * The reader asked to see the claims a column had no room for.
   *
   * The collapsed tile does not expand: it opens the outline, filtered to that
   * column. The outline is built from the world rather than from what is
   * painted, so those claims already have items there and the tile only has to
   * point at them.
   */
  readonly onOverflow: (column: { layer: number; claims: readonly string[] }) => void;
  /**
   * True while the map is arriving, which is when the one animation it spends on
   * causality runs: the wires draw in the order the argument runs, a column at a
   * time. Under reduced motion the ordering survives and the drawing goes.
   */
  readonly arriving: boolean;
  /**
   * The rectangles the map is holding open at its growing edge, while a map is
   * still being built.
   *
   * Empty on every finished map, which is every map this canvas drew before
   * generation existed — so nothing about a stored example changes.
   */
  readonly reserved?: readonly ReservedBox[];
  /**
   * What the canvas says about the session it is in, such as that this run is a
   * recording being played back. Drawn in the corner of the surface, over
   * nothing.
   */
  readonly badge?: ReactNode;
  /**
   * A word that changes when the map should be framed again.
   *
   * The map is framed once, when it is first drawn, and never again — losing
   * your place because the map was rearranged is the most disorienting thing a
   * canvas can do. A map that **builds itself** has one more moment worth
   * framing: the one where it stops. Nothing on it moves then, the reader is
   * about to start reading, and a four-column map framed for its first single
   * rectangle is a map they would otherwise have to hunt around.
   *
   * It is a word rather than a flag so that the effect has something to compare:
   * the map is framed once for each value it has ever had.
   */
  readonly frameAgainOn?: string;
}

/**
 * Keep asking the drawing library to measure the tiles' handles until it has.
 *
 * **A wire is drawn between two handles, and a handle's place is measured, not
 * declared.** #37 gave the library every tile's own box, because it draws
 * nothing it has not measured and a busy browser drops the size notifications
 * it measures through. That fixed the tile. It could not fix the wire: where a
 * handle sits *inside* a tile is not something a width and a height say, and
 * the library learns it from the same dropped notification.
 *
 * Measured, with every tile's notification dropped and the glass's kept: seven
 * tiles drawn, none hidden, twenty-eight handles on the glass — and **not one
 * arrow**. A causal map is its arrows; without them it is the wrong picture of
 * the argument, and a quiet one, because every claim is still there in its
 * place. The end-to-end suite met it about once in a hundred and sixty runs.
 *
 * `nodesInitialized` is false until every tile has handle bounds, so it is the
 * fact to act on rather than a guess about timing, and asking is a direct
 * measurement rather than another notification to be dropped. The asking stops
 * the moment the library says it has measured.
 *
 * @param ids Every tile on the glass, by identifier.
 */
function useHandlesTheLibraryHasMeasured(ids: readonly string[]): void {
  const measured = useNodesInitialized();
  const measureAgain = useUpdateNodeInternals();
  useEffect(() => {
    if (measured || ids.length === 0) {
      return;
    }
    // On a timer rather than on an animation frame: a browser produces no
    // frames while nothing on the page is changing, and nothing changing is
    // precisely the state this is for — #37 learnt that the hard way.
    measureAgain([...ids]);
    const asking = window.setInterval(() => measureAgain([...ids]), 120);
    return () => window.clearInterval(asking);
  }, [measured, ids, measureAgain]);
}

/** The surface itself. Lives inside the provider so it can move the view. */
function MapSurface({
  world,
  selection,
  onSelect,
  focused,
  onFocused,
  heights,
  mapKey,
  keys,
  onStatus,
  onOverflow,
  arriving,
  reserved,
  badge,
  frameAgainOn,
}: SurfaceProps) {
  const flow = useReactFlow();
  const surface = useRef<HTMLDivElement>(null);
  const [pointingAt, setPointingAt] = useState<string | null>(null);

  const drawing = useMemo(() => toFlow(world, heights, reserved), [world, heights, reserved]);
  // Every box the glass holds, by identifier — the list the measuring asks
  // about, held still so that the asking does not restart on every render.
  // A map that is still being built puts a new box in this list each time a
  // claim arrives, so the asking covers a tile that was not there before.
  const everyTile = useMemo(() => drawing.nodes.map((node) => node.id), [drawing.nodes]);
  useHandlesTheLibraryHasMeasured(everyTile);
  const layout = useLayout(drawing.tiles, drawing.layoutEdges, mapKey);

  // How far the map is zoomed out. Below the threshold a wire's plate would
  // have its words drawn under eleven pixels on the glass, which is the one
  // thing nothing in this product is allowed to do, so the plates go and the
  // stroke keeps saying what kind of push each wire is.
  const zoom = useStore((state) => state.transform[2]);
  const tooSmallForWords = zoom < SUMMARY_BELOW_ZOOM;

  /** How tall a tile turned out to be, so the view can be centred on its middle. */
  const heightOf = useCallback(
    (id: string) => drawing.tiles.find((tile) => tile.id === id)?.height ?? 0,
    [drawing],
  );

  /** Where every tile ended up, which is what routing a wire needs to know. */
  const boxes = useMemo(() => {
    const placed = new Map<string, Box>();
    for (const [id, at] of layout.positions) {
      placed.set(id, { x: at.x, y: at.y, width: TILE_WIDTH, height: heightOf(id) });
    }
    return placed;

/**
 * Where a tile's ports are, and the one place that says so.
 *
 * A **port** is the socket a wire attaches to. Every tile has four: a pair on
 * the left edge for arrows arriving and a pair on the right for arrows leaving,
 * and in each pair the upper socket is for an arrow that fires once and stays
 * fired, the lower for one that only holds while its cause holds. What a wire
 * means is visible at the socket before you follow it anywhere.
 *
 * **A port's place is declared, not discovered — and that is the whole point of
 * this file.** The drawing library draws a wire between two ports, and left to
 * itself it finds out where a port is by measuring the page, through the very
 * same browser notification a busy browser drops. A wire whose ends were never
 * measured is not drawn at all: the map holds every claim, in its place, and
 * says nothing about how they are joined, which is the wrong picture of the
 * argument and a silent one. #37 met the same dropped notification as tiles
 * that never appeared and answered it by telling the library each tile's box
 * outright. A box is not a port, so the wire half of it was left over. This is
 * the rest of the same answer: told its box *and* where its ports sit, a tile
 * can have its wires drawn on the first frame with nothing measured at all.
 *
 * So every number a port has is written here, and written **once**. The tile
 * puts these numbers straight onto the element it draws; the drawing library is
 * handed the same numbers; `wires/plates.ts` places a plate against them. This
 * file must never read a port's place back off the screen, and nothing else may
 * write one down a second time — two places that have to agree are two places
 * that one day will not.
 */

import type { NodeHandle } from "@xyflow/react";
import { Position } from "@xyflow/react";
import type { LinkMode } from "../world";
import { TILE_WIDTH } from "./geometry";

/**
 * How wide a port is, in pixels — two steps of the eight-pixel grid the whole
 * interface sits on.
 *
 * It straddles the tile's edge, half of it inside and half outside, which is
 * why it is exactly twice the standoff below.
 */
export const PORT_WIDTH = 16;

/** How tall a port is, in pixels: enough for one bar, a gap and a second bar. */
export const PORT_HEIGHT = 6;

/**
 * How far past the tile's edge a wire attaches, in pixels.
 *
 * A wire that met the tile flush would have its last few pixels drawn under the
 * tile's own outline. Eight pixels clear is one step of the grid.
 */
export const PORT_STANDOFF = 8;

/**
 * How far down a tile each of the two sockets sits, as a share of its height.
 *
 * A share rather than a number of pixels, because a tile is as tall as its own
 * content: the pair has to stay evenly spaced about the middle on a tile of any
 * height. Read by `wires/plates.ts` as well, which has to know where a wire
 * will start before a single wire has been drawn.
 */
export const DOWN_THE_TILE: Readonly<Record<LinkMode, number>> = {
  trigger: 0.38,
  sustain: 0.62,
};

/** What a port is called. These four names are what a wire names its ends by. */
export type PortId = "in-trigger" | "in-sustain" | "out-trigger" | "out-sustain";

/** One socket on the edge of a tile. */
export interface Port {
  /** Its name, which is what a wire asks for. */
  readonly id: PortId;
  /** Whether wires leave from it or arrive at it. */
  readonly kind: "source" | "target";
  /** Which edge of the tile it is on. */
  readonly edge: Position;
  /** Which kind of push attaches here. Also what the socket is drawn as. */
  readonly mode: LinkMode;
}

/**
 * The four ports every tile has, in the order they are drawn.
 *
 * Arriving before leaving, and within each pair the one that fires once before
 * the one that holds — the same top-to-bottom order the sockets are drawn in,
 * so the list reads the way the tile looks.
 */
export const PORTS: readonly Port[] = [
  { id: "in-trigger", kind: "target", edge: Position.Left, mode: "trigger" },
  { id: "in-sustain", kind: "target", edge: Position.Left, mode: "sustain" },
  { id: "out-trigger", kind: "source", edge: Position.Right, mode: "trigger" },
  { id: "out-sustain", kind: "source", edge: Position.Right, mode: "sustain" },
];

/** A port's box, in the tile's own coordinates, with the tile's corner at zero. */
export interface PortBox {
  /** Its left edge. Negative on the left of a tile: the port straddles the edge. */
  readonly x: number;
  /** Its top edge. */
  readonly y: number;
  /** How wide it is. */
  readonly width: number;
  /** How tall it is. */
  readonly height: number;
}

/**
 * Where this port sits on a tile of this height.
 *
 * The one piece of arithmetic in this file, and every other number here and in
 * the tile comes out of it. The box straddles the tile's edge so that the wire
 * attaches a clear eight pixels outside it, and it is centred on the share of
 * the height the socket sits at.
 *
 * @param height How tall the tile is — the same number the layout reserved for
 *   it and the same number the tile is drawn at. A tile that grew a line
 *   because an edit touched it moves its ports down with it, and this is where
 *   that happens.
 * @param port Which of the four.
 */
export function portBox(height: number, port: Port): PortBox {
  return {
    x: port.edge === Position.Left ? -PORT_STANDOFF : TILE_WIDTH + PORT_STANDOFF - PORT_WIDTH,
    y: height * DOWN_THE_TILE[port.mode] - PORT_HEIGHT / 2,
    width: PORT_WIDTH,
    height: PORT_HEIGHT,
  };
}

/**
 * Every port of a tile this tall, in the shape the drawing library takes them.
 *
 * Handed over with the tile's box, so that the library knows where both ends of
 * every wire are before it has measured anything. It keeps measuring afterwards
 * and rebuilds these from what it measures; the numbers are the same numbers,
 * because the tile was drawn from them.
 *
 * @param height How tall the tile is.
 */
export function portsOf(height: number): NodeHandle[] {
  return PORTS.map((port) => ({
    id: port.id,
    type: port.kind,
    position: port.edge,
    ...portBox(height, port),
  }));
}

/**
 * Which port a wire of this kind leaves from, and which it arrives at.
 *
 * @param mode Whether the push fires once or has to keep holding.
 */
export function portsForAWire(mode: LinkMode): {
  readonly source: PortId;
  readonly target: PortId;
} {
  return mode === "sustain"
    ? { source: "out-sustain", target: "in-sustain" }
    : { source: "out-trigger", target: "in-trigger" };
}

